  constructor(
    private engine: PcbEngine,
    private args: AddTraceArgs,
    private refreshSnapshot: () => void,
  ) {
    this.description = `Add trace: ${args.netName} on ${args.layer}`;
  }

  execute(): void {
    this.traceId = this.engine.add_trace(
      this.args.netName,
      this.args.layer,
      this.args.width,
      this.args.segments,
    );
